INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',674,'{"_type":"chat:Message","id":"-5124234082:3156","threadId":"telegram:-5124234082","text":"Ce midi on a mange pollo chipotle riz, ce soir on a diné dehors. Les enfants ont mangé du riz avec du jambon et de l’avocat.  \nDemain midi salade de riz au parc. Donne nous une recette de salade de riz pour demain midi demain matin à 8h.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Ce midi on a mange pollo chipotle riz, ce soir on a diné dehors. Les enfants ont mangé du riz avec du jambon et de l’avocat.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":125,"offset":124}}},{"type":"break","position":{"start":{"line":1,"column":125,"offset":124},"end":{"line":2,"column":1,"offset":127}}},{"type":"text","value":"Demain midi salade de riz au parc. Donne nous une recette de salade de riz pour demain midi demain matin à 8h.","position":{"start":{"line":2,"column":1,"offset":127},"end":{"line":2,"column":111,"offset":237}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":111,"offset":237}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":111,"offset":237}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-09-05T22:08:22.000Z","edited":false},"attachments":[],"isMention":false}',1789250900967);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',696,'{"_type":"chat:Message","id":"8641420749:1591","threadId":"telegram:8641420749","text":"Hier je suis allé faire un massage sportif des jambes le matin pour ma douleur à la cuisse. Ça a été très intense car depuis mon dernier massage sportif j’ai roulé 1200km. Ils m’ont conseillé de ne pas pedaler le même jour. \nHier soir j’avais une legere douleur dans la gorge quand j’avalais. Cette nuit j’ai dormi de minuit à 8h mais tres tres interrompu, j’ai eu bcp plus mal à la gorge. J’ai pris un paracetamol à 8h, redoxon, lavage de nez car je sentais que c’était bouche mais tres sec. Je prendrai du propolis max 15% tout a l’heure quand je rentre a la maison. La ca va mieux avec le paracetamol. J’irai peut etre pedaler un peu pour voir si la douleur a la cuisse a disparu mais certainement pas 3h. On verta d’ici 2/3h quand l’effet du paracetamol aura disparu. \nComment tu analyses la situation ? Quel est ton diagnostic et recommendation ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Hier je suis allé faire un massage sportif des jambes le matin pour ma douleur à la cuisse. Ça a été très intense car depuis mon dernier massage sportif j’ai roulé 1200km. Ils m’ont conseillé de ne pas pedaler le même jour.\nHier soir j’avais une legere douleur dans la gorge quand j’avalais. Cette nuit j’ai dormi de minuit à 8h mais tres tres interrompu, j’ai eu bcp plus mal à la gorge. J’ai pris un paracetamol à 8h, redoxon, lavage de nez car je sentais que c’était bouche mais tres sec. Je prendrai du propolis max 15% tout a l’heure quand je rentre a la maison. La ca va mieux avec le paracetamol. J’irai peut etre pedaler un peu pour voir si la douleur a la cuisse a disparu mais certainement pas 3h. On verta d’ici 2/3h quand l’effet du paracetamol aura disparu.\nComment tu analyses la situation ? Quel est ton diagnostic et recommendation ?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":79,"offset":851}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":79,"offset":851}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":79,"offset":851}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-09-06T10:00:39.000Z","edited":false},"attachments":[],"isMention":false}',1789293638724);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',697,'{"_type":"chat:Message","id":"8641420749:1593","threadId":"telegram:8641420749","text":"Ce qui m’inquiète c’est d’arrêter de pédaler si je suis malade. Je sais que le fait de ne pas avoir pédaler completement pendant 10 jours ou plus avant Paris Marseille a contribué à l’inflammation du genou. \nJe verrai tout à l’heure comment je me sens et j’irai peut etre pédaler juste 1h en Z1","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Ce qui m’inquiète c’est d’arrêter de pédaler si je suis malade. Je sais que le fait de ne pas avoir pédaler completement pendant 10 jours ou plus avant Paris Marseille a contribué à l’inflammation du genou.\nJe verrai tout à l’heure comment je me sens et j’irai peut etre pédaler juste 1h en Z1","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":87,"offset":294}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":87,"offset":294}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":87,"offset":294}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-09-06T10:36:52.000Z","edited":false},"attachments":[],"isMention":false}',1789295811949);
