INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',701,'{"_type":"chat:Message","id":"8641420749:1601","threadId":"telegram:8641420749","text":"J’ai pris rdv chez le medecin demain matin pour la gorge. Là après le ride je me sens faible. Donc oui ça n’a pas impacté ce ride, mais je suis bel et bien malade et mon corps se concentre sur la recup. Donc 2h Z2 demain ça ne marchera peut etre pas.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"J’ai pris rdv chez le medecin demain matin pour la gorge. Là après le ride je me sens faible. Donc oui ça n’a pas impacté ce ride, mais je suis bel et bien malade et mon corps se concentre sur la recup. Donc 2h Z2 demain ça ne marchera peut etre pas.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":251,"offset":250}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":251,"offset":250}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":251,"offset":250}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-09-06T16:41:34.000Z","edited":false},"attachments":[],"isMention":false}',1789317693568);
